import{_ as e,o as s,c as n,S as l}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"Archlinux下有关无损音乐的折腾","description":"","frontmatter":{"title":"Archlinux下有关无损音乐的折腾","date":"2013-10-06 23:29","comments":true,"archives":2013,"tags":["linux","music"]},"headers":[],"relativePath":"posts/2013-10-06-archlinux-ape-cue-splitting/index.md","filePath":"posts/2013/2013-10-06-Archlinux-ape-cue-splitting.md"}'),p={name:"posts/2013-10-06-archlinux-ape-cue-splitting/index.md"};function t(o,a,r,c,i,d){return s(),n("div",null,[...a[0]||(a[0]=[l('<p>最近发现一些旧番的音乐只有无损的了...MP3 的已经无法满足大众的需求了么....<br> 但是在 Linux 下直接用 MPD 播放无损音乐不能分轨播放实在是不能接受. 于是就开始找寻切割的方法...Archwiki 有相关的条目<a href="https://wiki.archlinux.org/index.php/APE%2BCUE_Splitting" target="_blank" rel="noreferrer">APE+CUE Splitting</a> 但是,有个明显的缺陷是分轨之后的文件居然不是用歌曲名字命名的! 而且还是我不怎么喜欢的 wav 格式... 不过我还是在菊苣的帮助下找到了完美的解决方案~</p><h2 id="无损音乐的分轨" tabindex="-1">无损音乐的分轨 <a class="header-anchor" href="#无损音乐的分轨" aria-label="Permalink to &quot;无损音乐的分轨&quot;">​</a></h2><p>Linux 下有个 shntool 的工具非常实用,可以完美解决无损音乐分轨的问题. 根本不需要 wiki 里面说的 cuebreakpoints</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">shntool</span><span style="color:#032F62;"> split</span><span style="color:#005CC5;"> -f</span><span style="color:#032F62;"> example.cue</span><span style="color:#005CC5;"> -t</span><span style="color:#032F62;"> %n_%p_%t</span><span style="color:#005CC5;"> -o</span><span style="color:#032F62;"> &#39;cust ext=mp3 lame --quiet - %f&#39;</span><span style="color:#032F62;"> example.ape</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>-t 指的是文件的标题,%n 代表编号,%p 表示 Performer，%t 表示 Title.都是从 cue 里面读取的信息,shntool 默认不支持 mp3 格式的,所以需要指定用 lame 编码器进行编码.当然很多人只是想分轨,并不想转换成压缩的 mp3 格式.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">shntool</span><span style="color:#032F62;"> split</span><span style="color:#005CC5;"> -f</span><span style="color:#032F62;"> example.cue</span><span style="color:#005CC5;"> -t</span><span style="color:#032F62;"> %n_%p_%t</span><span style="color:#005CC5;"> -o</span><span style="color:#032F62;"> flac</span><span style="color:#032F62;"> example.ape</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>直接转换成 flac 格式就好了,因为 flac 格式是开源的无损音乐格式,播放器对它支持的肯定比较好. 如果出现 <code>warning: failed to read data from input file using format: [ape]</code> 这样的错误可能需要安装<a href="https://www.archlinux.org/packages/community/x86_64/mac/" target="_blank" rel="noreferrer">mac</a></p><h2 id="给每个音乐文件打-tag" tabindex="-1">给每个音乐文件打 TAG <a class="header-anchor" href="#给每个音乐文件打-tag" aria-label="Permalink to &quot;给每个音乐文件打 TAG&quot;">​</a></h2><p>转换之后的文件只是单纯的音乐文件,每个音乐并没有包含想关的 TAG 信息,这时候需要用 cuetag.sh 给每个音乐文件打 TAG<br><a href="https://gist.github.com/acgotaku/7279681" target="_blank" rel="noreferrer">cuetag.sh 脚本</a> 最新版貌似有问题不能使用.<br><code>cuetag.sh file.cue *.mp3</code><br> 命令很简单,在转换好的音乐文件夹下指定 cue 文件和 mp3 文件即可自动打 TAG,但是需要注意的一点是,这个脚本打的是 ID3v1 的标签,如果是非英语语言的话, 会出现乱码问题.详情请戳<a href="http://linux-wiki.cn/wiki/Mp3%E6%A0%87%E7%AD%BE%E4%B9%B1%E7%A0%81%E9%97%AE%E9%A2%98%E5%88%86%E6%9E%90%E4%B8%8E%E8%A7%A3%E5%86%B3%E6%96%B9%E6%A1%88" target="_blank" rel="noreferrer">Mp3 标签乱码问题分析与解决方案</a> 所以,之后我们还是要使用<a href="https://code.google.com/p/mp3tagiconv/" target="_blank" rel="noreferrer">mp3tagiconv</a> 这个工具来进行标签的转换使得所有的播放器都能够正确识别 mp3 音乐的标签.<br><code>for i in *.mp3; do echo &quot;y&quot;| mp3tagiconv &quot;${i}&quot; ;done</code><br> 因为 mp3tagiconv 这个工具每次更新标签都会提示 yes or no ,所以我就修改了下执行方式,使得批量自动化修改.flac 格式的音乐不存在 TAG 编码问题.</p><h2 id="flac-转换为-mp3" tabindex="-1">flac 转换为 mp3 <a class="header-anchor" href="#flac-转换为-mp3" aria-label="Permalink to &quot;flac 转换为 mp3&quot;">​</a></h2><p>虽然在 PC 上听无损比较爽,但是放在手机上受制于存储空间和 CPU 性能,还是转换成 Mp3 比较好.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">flac</span><span style="color:#005CC5;"> -d</span><span style="color:#005CC5;"> -c</span><span style="color:#032F62;"> example.flac</span><span style="color:#D73A49;"> |</span><span style="color:#6F42C1;"> lame</span><span style="color:#005CC5;"> -q</span><span style="color:#005CC5;"> 0</span><span style="color:#005CC5;"> -b</span><span style="color:#005CC5;"> 320</span><span style="color:#032F62;"> -</span><span style="color:#032F62;"> example.mp3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果想保留 flac 的回放增益特性的话可以在转换的时候加上<code>--apply-replaygain-which-is-not-lossless</code> 参数.</p><p>到此,折腾完毕...</p>',14)])])}const m=e(p,[["render",t]]);export{h as __pageData,m as default};
